{
  "title": "Eat Your Way Through Kyoto",
  "summary": "A slower, tastier day built around Rin's appetite, with a market, a proper lunch, and an evening meal without leaving the same corner of the city.",
  "stops": [
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "Still the one we keep. Shoes off, phone down, eyes up before the eating begins."
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "Rin's first excuse to graze. A market stop is a meal with extra steps, and these steps are delicious."
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "A proper bowl, cheap and cheerful. Lunch stays because even a food day needs a table to lean on."
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle wander to settle the noodles. History and local life, no ticket required."
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner with a little theatre. Rin gets her second proper meal, and the rest of us get to watch an omelette show."
    }
  ]
}
